#include <bits/stdc++.h>
using namespace std;
#define int long long
int check(int k1,int k2,vector<int>&temp){
    int a = 6*temp[k1];
    int b = 4*(temp[k1+2*k2]-temp[k1]);
    int c = 3*(temp[temp.size()-1 -(2*k1 + k2)]-temp[k1+2*k2]);
    return a+b+c;
}

signed  main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        n= 3*n;
        vector<int>v(n);
        for(auto &it:v)cin>>it;
        sort(v.begin(),v.end(),greater<int>());
        vector<int>pfsum(n+1,0);
        for(int i=1;i<=n;i++){
            pfsum[i]=pfsum[i-1]+v[i-1];
        }
        int ans=0;
        for(int k1=0;k1<=n;k1++){
            int tempans=-1,l=0;
            int r = ((n-3*k1)/3);
            while((r-l)>3){
                int m1 = l + ((r-l)/3);
                int m2 = r- ((r-l)/3);
                if(check(k1,m1,pfsum)<check(k1,m2,pfsum)){
                    l=m1+1;
                    ans = max(ans,check(k1,m2,pfsum));
                }
                else {
                    r=m2-1;
                    ans=max(ans,check(k1,m1,pfsum));
                }
            }
            for(int i=l;i<=r;i++){
                ans = max(ans,check(k1,i,pfsum));
            }
        }
        
        cout<<ans<<endl;
    }
}
